import{_ as e,c as r,o as i,ah as n}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"38、【睽】 兌下離上","description":"溫公易說 - 38、【睽】 兌下離上","frontmatter":{"title":"38、【睽】 兌下離上","description":"溫公易說 - 38、【睽】 兌下離上"},"headers":[],"relativePath":"classics/wengong/039.md","filePath":"classics/wengong/039.md"}'),l={name:"classics/wengong/039.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_38、【睽】-兌下離上" tabindex="-1">38、【睽】 兌下離上 <a class="header-anchor" href="#_38、【睽】-兌下離上" aria-label="Permalink to “38、【睽】 兌下離上”">​</a></h1><p>注意</p><p>案原本缺。</p><h3 id="彖曰-睽-火動而上-澤動而下。二女同居-其志不同。行說而麗乎明-柔進而上行-得中而應乎剛-是以小事吉。天地睽而其事同也-男女睽而其志通也-萬物睽而其事類也。睽之時用大矣哉。" tabindex="-1">彖曰：睽，火動而上，澤動而下。二女同居，其志不同。行說而麗乎明，柔進而上行，得中而應乎剛，是以小事吉。天地睽而其事同也，男女睽而其志通也，萬物睽而其事類也。睽之時用大矣哉。 <a class="header-anchor" href="#彖曰-睽-火動而上-澤動而下。二女同居-其志不同。行說而麗乎明-柔進而上行-得中而應乎剛-是以小事吉。天地睽而其事同也-男女睽而其志通也-萬物睽而其事類也。睽之時用大矣哉。" aria-label="Permalink to “彖曰：睽，火動而上，澤動而下。二女同居，其志不同。行說而麗乎明，柔進而上行，得中而應乎剛，是以小事吉。天地睽而其事同也，男女睽而其志通也，萬物睽而其事類也。睽之時用大矣哉。”">​</a></h3><h3 id="象曰-上火下澤-睽。君子以同而異。" tabindex="-1">象曰：上火下澤，睽。君子以同而異。 <a class="header-anchor" href="#象曰-上火下澤-睽。君子以同而異。" aria-label="Permalink to “象曰：上火下澤，睽。君子以同而異。”">​</a></h3><h3 id="初九-悔亡-喪馬勿逐-自復-見惡人-無咎-象曰-見惡人-以闢咎也。" tabindex="-1">初九：悔亡，喪馬勿逐，自復；見惡人，無咎 象曰：見惡人，以闢咎也。 <a class="header-anchor" href="#初九-悔亡-喪馬勿逐-自復-見惡人-無咎-象曰-見惡人-以闢咎也。" aria-label="Permalink to “初九：悔亡，喪馬勿逐，自復；見惡人，無咎 象曰：見惡人，以闢咎也。”">​</a></h3><h3 id="九二-遇主於巷-無咎-象曰-遇主於巷-未失道也。" tabindex="-1">九二：遇主於巷，無咎 象曰：遇主於巷，未失道也。 <a class="header-anchor" href="#九二-遇主於巷-無咎-象曰-遇主於巷-未失道也。" aria-label="Permalink to “九二：遇主於巷，無咎 象曰：遇主於巷，未失道也。”">​</a></h3><h3 id="六三-見輿曵-其牛掣-其人天且劓-無初有終-象曰-見輿曵-位不當也-無初有終-遇剛也。" tabindex="-1">六三：見輿曵，其牛掣，其人天且劓，無初有終 象曰：見輿曵，位不當也；無初有終，遇剛也。 <a class="header-anchor" href="#六三-見輿曵-其牛掣-其人天且劓-無初有終-象曰-見輿曵-位不當也-無初有終-遇剛也。" aria-label="Permalink to “六三：見輿曵，其牛掣，其人天且劓，無初有終 象曰：見輿曵，位不當也；無初有終，遇剛也。”">​</a></h3><h3 id="九四-睽孤-遇元夫-交孚-厲無咎-象曰-交孚無咎-志行也。" tabindex="-1">九四：睽孤，遇元夫，交孚，厲無咎 象曰：交孚無咎，志行也。 <a class="header-anchor" href="#九四-睽孤-遇元夫-交孚-厲無咎-象曰-交孚無咎-志行也。" aria-label="Permalink to “九四：睽孤，遇元夫，交孚，厲無咎 象曰：交孚無咎，志行也。”">​</a></h3><h3 id="六五-悔亡-厥宗噬膚-往何咎-象曰-厥宗噬膚-往有慶也。" tabindex="-1">六五：悔亡，厥宗噬膚，往何咎 象曰：厥宗噬膚，往有慶也。 <a class="header-anchor" href="#六五-悔亡-厥宗噬膚-往何咎-象曰-厥宗噬膚-往有慶也。" aria-label="Permalink to “六五：悔亡，厥宗噬膚，往何咎 象曰：厥宗噬膚，往有慶也。”">​</a></h3><h3 id="上九-睽孤-見豕負塗-載鬼一車-先張之弧-後說之弧-匪寇婚媾。往遇雨則吉-象曰-遇雨之吉-群疑亡也。" tabindex="-1">上九：睽孤，見豕負塗，載鬼一車，先張之弧，後說之弧，匪寇婚媾。往遇雨則吉 象曰：遇雨之吉，群疑亡也。 <a class="header-anchor" href="#上九-睽孤-見豕負塗-載鬼一車-先張之弧-後說之弧-匪寇婚媾。往遇雨則吉-象曰-遇雨之吉-群疑亡也。" aria-label="Permalink to “上九：睽孤，見豕負塗，載鬼一車，先張之弧，後說之弧，匪寇婚媾。往遇雨則吉 象曰：遇雨之吉，群疑亡也。”">​</a></h3>',11)])])}const m=e(l,[["render",t]]);export{b as __pageData,m as default};
